function canArrange(arr, k) {
  const used = new Array(arr.length).fill(false);
  for (let i = 0; i < arr.length; i++) {
    if (used[i]) continue;
    let partner = -1;
    for (let j = i + 1; j < arr.length; j++) {
      if (!used[j] && (arr[i] + arr[j]) % k === 0) { partner = j; break; }   // any fitting partner will do
    }
    if (partner === -1) return false;                // arr[i] can't be paired
    used[i] = used[partner] = true;
  }
  return true;
}

