function canArrange(arr, k) {
  const rem = arr.map((x) => ((x % k) + k) % k).sort((a, b) => a - b);
  let i = 0;
  while (i < rem.length && rem[i] === 0) i++;        // multiples of k pair with each other
  if (i % 2 !== 0) return false;
  for (let j = rem.length - 1; i < j; i++, j--) {
    if (rem[i] + rem[j] !== k) return false;          // the smallest left must pair with the largest
  }
  return true;
}

boolean canArrange(int[] arr, int k) {
    int[] rem = new int[arr.length];
    for (int t = 0; t < arr.length; t++) rem[t] = ((arr[t] % k) + k) % k;
    Arrays.sort(rem);
    int i = 0;
    while (i < rem.length && rem[i] == 0) i++;         // multiples of k pair with each other
    if (i % 2 != 0) return false;
    for (int j = rem.length - 1; i < j; i++, j--) {
        if (rem[i] + rem[j] != k) return false;        // the smallest left must pair with the largest
    }
    return true;
}

bool canArrange(vector<int>& arr, int k) {
    vector<int> rem;
    for (int x : arr) rem.push_back(((x % k) + k) % k);
    sort(rem.begin(), rem.end());
    int i = 0;
    while (i < (int)rem.size() && rem[i] == 0) i++;    // multiples of k pair with each other
    if (i % 2 != 0) return false;
    for (int j = (int)rem.size() - 1; i < j; i++, j--) {
        if (rem[i] + rem[j] != k) return false;        // the smallest left must pair with the largest
    }
    return true;
}

function canArrange(arr, k) {
  const count = new Map();                            // remainder -> how many
  for (const x of arr) {
    const r = ((x % k) + k) % k;                      // 0..k-1, even for negatives
    count.set(r, (count.get(r) ?? 0) + 1);
  }
  for (const [r, c] of count) {
    if (r === 0 || 2 * r === k) {
      if (c % 2 !== 0) return false;                  // these pair among themselves
    } else if (c !== (count.get(k - r) ?? 0)) {
      return false;                                   // every r needs its own k - r
    }
  }
  return true;
}

from collections import Counter

def can_arrange(arr, k):
    count = Counter(x % k for x in arr)           # remainder -> how many
    for r, c in count.items():
        if r == 0 or 2 * r == k:
            if c % 2:
                return False                      # these pair among themselves
        elif c != count[k - r]:
            return False                          # every r needs its own k - r
    return True

boolean canArrange(int[] arr, int k) {
    Map<Integer, Integer> count = new HashMap<>();        // remainder -> how many
    for (int x : arr) count.merge(((x % k) + k) % k, 1, Integer::sum);   // 0..k-1, even for negatives
    for (Map.Entry<Integer, Integer> e : count.entrySet()) {
        int r = e.getKey(), c = e.getValue();
        if (r == 0 || 2 * r == k) {
            if (c % 2 != 0) return false;                 // these pair among themselves
        } else if (c != count.getOrDefault(k - r, 0)) {
            return false;                                 // every r needs its own k - r
        }
    }
    return true;
}

bool canArrange(vector<int>& arr, int k) {
    unordered_map<int, int> count;                    // remainder -> how many
    for (int x : arr) count[((x % k) + k) % k]++;     // 0..k-1, even for negatives
    for (auto& [r, c] : count) {
        if (r == 0 || 2 * r == k) {
            if (c % 2 != 0) return false;             // these pair among themselves
        } else {
            auto it = count.find(k - r);              // find, not [], so nothing is inserted mid-loop
            if (it == count.end() || it->second != c) return false;   // every r needs its own k - r
        }
    }
    return true;
}
